    feature3Title: 'క్యూఆర్ కోడ్ ధృవీకరణ:',
    feature3Desc: 'మార్కెట్ ప్రవేశం వద్ద వేగవంతమైన కాంటాక్ట్‌లెస్ ఎంట్రీ.',
    feature4Title: 'డిజిటల్ జే-ఫారం (J-Form):',
    feature4Desc: 'తూకం పూర్తయిన వెంటనే డిజిటల్ జే-ఫారం డౌన్‌లోడ్ చేసుకోండి.',
