    feature5Desc: '48 గంటల్లో నేరుగా మీ బ్యాంక్ ఖాతాలో సురక్షిత చెల్లింపు.',
    stepsTag: 'సరళమైన మరియు వేగవంతమైన విధానం',
    stepsTitle: 'సేకరణ ప్రక్రియ ఎలా పనిచేస్తుంది?',
    stepsDesc: 'మార్కెట్ వద్ద అనవసర నిరీక్షణ లేకుండా — పారదర్శక డిజిటల్ దశల్లో పంటను విక్రయించండి.',
    step1Title: '1. పంట & స్లాట్ ఎంపిక',
    step1Desc: 'పంట, పరిమాణం (క్వింటాళ్లు) మరియు సమీప కేంద్రాన్ని ఎంచుకుని సమయాన్ని రిజర్వ్ చేయండి.',
    step2Title: '2. క్యూఆర్ & టోకెన్ రసీదు',
    step2Desc: 'బుకింగ్ పూర్తి కాగానే డిజిటల్ టోకెన్ వస్తుంది. సమయానికి 10 నిమిషాల ముందే చేరుకోండి.',
