    step4Title: '4. నాణ్యత తనిఖీ & తూకం',
    step4Desc: 'తేమ శాతం తనిఖీ మరియు ఆటోమేటిక్ కాంటా ద్వారా ఖచ్చితమైన బరువు నమోదు.',
    step5Title: '5. డిజిటల్ జే-ఫారం',
    step5Desc: 'తూకం పూర్తయిన వెంటనే అధికారిక జే-ఫారం జారీ చేయబడుతుంది.',
