    heroCtaCenters: 'ਨੇੜਲਾ ਕੇਂਦਰ ਲੱਭੋ',
    featuresTitle: 'ਪੋਰਟਲ ਦੀਆਂ ਮੁੱਖ ਡਿਜੀਟਲ ਸਹੂਲਤਾਂ',
