    feature1Desc: 'ਪ੍ਰਤੀ ਕੁਇੰਟਲ ਪ੍ਰੋਸੈਸਿੰਗ ਸਮੇਂ ਅਨੁਸਾਰ ਸਹੀ ਸਮਾਂ।',
    feature2Title: 'ਲਾਈਵ ਟੋਕਨ ਕਤਾਰ:',
    feature2Desc: 'ਮੰਡੀ ਪਹੁੰਚਣ ਤੋਂ ਪਹਿਲਾਂ ਮੋਬਾਈਲ ਤੇ ਕਤਾਰ ਦੀ ਸਥਿਤੀ ਦੇਖੋ।',
