    feature5Desc: '48 ਘੰਟਿਆਂ ਵਿੱਚ ਸਿੱਧੇ ਬੈਂਕ ਖਾਤੇ ਵਿੱਚ ਸੁਰੱਖਿਅਤ ਭੁਗਤਾਨ।',
