    stepsDesc: 'ਮੰਡੀ ਵਿੱਚ ਬੇਲੋੜੀਆਂ ਲਾਈਨਾਂ ਤੋਂ ਛੁਟਕਾਰਾ — ਪਾਰਦਰਸ਼ੀ ਡਿਜੀਟਲ ਕਦਮਾਂ ਵਿੱਚ ਫਸਲ ਵੇਚੋ।',
