    heroDesc: 'ଅନ୍ନଦାତା ଚାଷୀ ଭାଇମାନଙ୍କ ପାଇଁ ସ୍ୱଚ୍ଛ ଡିଜିଟାଲ୍ ସ୍ଲଟ୍ ବୁକିଂ, ଲାଇଭ୍ ଧାଡ଼ି ଟ୍ରାକିଂ, କମ୍ପ୍ୟୁଟରାଇଜ୍ଡ ଓଜନ ଏବଂ ୪୮ ଘଣ୍ଟା ମଧ୍ୟରେ ସିଧାସଳଖ ବ୍ୟାଙ୍କ ଖାତାରେ ଏମ୍ଏସପି ପ୍ରଦାନ।',
    heroCtaStart: 'ଚାଷୀ ଭାବରେ ଆରମ୍ଭ କରନ୍ତୁ',
    heroCtaCenters: 'ନିକଟତମ କେନ୍ଦ୍ର ଖୋଜନ୍ତୁ',
    featuresTitle: 'ପୋର୍ଟାଲର ପ୍ରମୁଖ ଡିଜିଟାଲ୍ ସୁବିଧା',
    feature1Title: 'ଡାଇନାମିକ୍ ସ୍ଲଟ୍ ଆବଣ୍ଟନ:',
    feature1Desc: 'ପ୍ରତି କ୍ୱିଣ୍ଟାଲ୍ ପ୍ରକ୍ରିୟାକରଣ ସମୟ ଅନୁଯାୟୀ ସଠିକ୍ ସମୟ।',
    feature2Title: 'ଲାଇଭ୍ ଟୋକନ୍ ଧାଡ଼ି:',
    feature2Desc: 'ମଣ୍ଡିରେ ପହଞ୍ଚିବା ପୂର୍ବରୁ ମୋବାଇଲରେ ଧାଡ଼ି ସ୍ଥିତି ଦେଖନ୍ତୁ।',
    feature3Title: 'QR କୋଡ୍ ଯାଞ୍ଚ:',
    feature3Desc: 'ପ୍ରବେଶ ଦ୍ୱାରରେ ଶୀଘ୍ର ଏବଂ ସମ୍ପର୍କବିହୀନ ପ୍ରବେଶ।',
    feature4Title: 'ଡିଜିଟାଲ୍ ଜେ-ଫର୍ମ (J-Form):',
    feature4Desc: 'ଓଜନ ଶେଷ ହେବା ମାତ୍ରେ ଡିଜିଟାଲ୍ ରସିଦ୍ ଡାଉନଲୋଡ୍ କରନ୍ତୁ।',
    feature5Title: 'ପ୍ରତ୍ୟକ୍ଷ ଲାଭ ହସ୍ତାନ୍ତର (DBT):',
    feature5Desc: '୪୮ ଘଣ୍ଟା ମଧ୍ୟରେ ସିଧାସଳଖ ବ୍ୟାଙ୍କ ଖାତାରେ ସୁରକ୍ଷିତ ପେମେଣ୍ଟ।',
    stepsTag: 'ସରଳ ଏବଂ ସୁବିଧାଜନକ ପ୍ରକ୍ରିୟା',
    stepsTitle: 'କ୍ରୟ ପ୍ରକ୍ରିୟା କିପରି କାର୍ଯ୍ୟ କରେ?',
    stepsDesc: 'ମଣ୍ଡିରେ ଅନାବଶ୍ୟକ ଧାଡ଼ିରୁ ମୁକ୍ତି — ଡିଜିଟାଲ୍ ପଦ୍ଧତିରେ ନିଜ ଫସଲ ବିକ୍ରି କରନ୍ତୁ।',
    step1Title: '୧. ଫସଲ ଓ ସ୍ଲଟ୍ ଚୟନ',
    step1Desc: 'ଫସଲ, ପରିମାଣ (କ୍ୱିଣ୍ଟାଲ୍) ଏବଂ ନିକଟତମ କେନ୍ଦ୍ର ଚୟନ କରି ସମୟ ବୁକ୍ କରନ୍ତୁ।',
    step2Title: '୨. QR ଓ ଟୋକନ୍ ରସିଦ୍',
    step2Desc: 'ବୁକିଂ ହେବା ମାତ୍ରେ ଡିଜିଟାଲ୍ ଟୋକନ୍ ମିଳିବ। ୧୦ ମିନିଟ୍ ପୂର୍ବରୁ ପହଞ୍ଚନ୍ତୁ।',
    step3Title: '୩. ଲାଇଭ୍ ଧାଡ଼ି ଓ କାଉଣ୍ଟର',
    step3Desc: 'QR ସ୍କାନ୍ ହେବା ମାତ୍ରେ ଆଗମନ ପଞ୍ଜୀକୃତ ହୋଇ କାଉଣ୍ଟର ନମ୍ବର ମିଳିବ।',
    step4Title: '୪. ଗୁଣବତ୍ତା ଯାଞ୍ଚ ଓ ଓଜନ',
    step4Desc: 'ଆର୍ଦ୍ରତା ପରୀକ୍ଷା ଏବଂ ସ୍ୱୟଂଚାଳିତ କଣ୍ଟାରେ ସଠିକ୍ ଓଜନ ଗ୍ରହଣ।',
    step5Title: '୫. ଡିଜିଟାଲ୍ ଜେ-ଫର୍ମ',
    step5Desc: 'ଓଜନ ସରିବା ପରେ ସରକାରୀ ଜେ-ଫର୍ମ ଜାରି ହୋଇଥାଏ।',
    step6Title: '୬. ସିଧାସଳଖ ବ୍ୟାଙ୍କ ପେମେଣ୍ଟ (DBT)',
    step6Desc: 'ଏମ୍ଏସପି ଟଙ୍କା ସିଧାସଳଖ ଚାଷୀଙ୍କ ଆଧାର ଲିଙ୍କ୍ ବ୍ୟାଙ୍କ ଖାତାରେ ଜମା ହୁଏ।',
